examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    MonarchAiAutofillField(
        state: state0,
        suggestion: {{fields.0.suggestion}},
        fieldName: {{fields.0.label}}.lowercased(),
        source: {{fields.0.source}},
        confidence: {{fields.0.confidence}},
        onAccept: { state0 = .accepted },
        onClear: {
            value0 = ""
            state0 = .cleared
        },
        control: { MonarchTextField({{fields.0.label}}, text: $value0) }
    )
    MonarchAiAutofillField(
        state: state1,
        suggestion: {{fields.1.suggestion}},
        fieldName: {{fields.1.label}}.lowercased(),
        source: {{fields.1.source}},
        confidence: {{fields.1.confidence}},
        onAccept: { state1 = .accepted },
        onClear: {
            value1 = ""
            state1 = .cleared
        },
        control: { MonarchTextField({{fields.1.label}}, text: $value1) }
    )
    MonarchAiAutofillField(
        state: state2,
        suggestion: {{fields.2.suggestion}},
        fieldName: {{fields.2.label}}.lowercased(),
        confidence: {{fields.2.confidence}},
        onAccept: { state2 = .accepted },
        onClear: {
            value2 = ""
            state2 = .cleared
        },
        control: { MonarchTextField({{fields.2.label}}, text: $value2) }
    )
}
.frame(maxWidth: 416)

examples.setupTemplate:
@State private var value0 = {{fields.0.suggestion}}
@State private var state0: MonarchAiAutofillState = .suggested
@State private var value1 = {{fields.1.suggestion}}
@State private var state1: MonarchAiAutofillState = .suggested
@State private var value2 = {{fields.2.suggestion}}
@State private var state2: MonarchAiAutofillState = .suggested

examples.setup:
@State private var value0 = "Northwind Ltd"
@State private var state0: MonarchAiAutofillState = .suggested
@State private var value1 = "1,240.00"
@State private var state1: MonarchAiAutofillState = .suggested
@State private var value2 = "2026-05-30"
@State private var state2: MonarchAiAutofillState = .suggested

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    MonarchAiAutofillField(
        state: state0,
        suggestion: "Northwind Ltd",
